type CourseState =
  | { status: "loading" }
  | { status: "success"; data: Course[] }
  | { status: "error"; message: string };

function Courses() {
  const [state, setState] = useState<CourseState>({ status: "loading" });

  useEffect(() => {
    const controller = new AbortController();

    async function loadCourses() {
      try {
        const response = await fetch("/api/courses", {
          signal: controller.signal
        });
        if (!response.ok) {
          throw new Error("Unable to retrieve courses");
        }
        const data: unknown = await response.json();
        // Production code should validate every course.
        if (!Array.isArray(data)) {
          throw new Error("Invalid course response");
        }
        setState({ status: "success", data: data as Course[] });
      } catch (error) {
        if (error instanceof Error && error.name !== "AbortError") {
          setState({ status: "error", message: error.message });
        }
      }
    }

    loadCourses();
    return () => controller.abort();
  }, []);

  if (state.status === "loading") {
    return <p>Loading courses...</p>;
  }
  if (state.status === "error") {
    return <p>{state.message}</p>;
  }
  return (
    <div>
      {state.data.map(course => (
        <p key={course.id}>{course.title}</p>
      ))}
    </div>
  );
}

