type ApiState<T> =
  | { status: "loading" }
  | { status: "success"; data: T }
  | { status: "empty"; data: T }
  | { status: "error"; message: string };

function CoursePage() {
  const [state, setState] = useState<ApiState<Course[]>>({ status: "loading" });

  useEffect(() => {
    const controller = new AbortController();

    async function loadCourses() {
      try {
        const response = await fetch("/api/courses", {
          signal: controller.signal
        });
        if (!response.ok) {
          throw new Error("Course retrieval failed");
        }
        const data: unknown = await response.json();
        const result = CoursesSchema.safeParse(data);
        if (!result.success) {
          throw new Error("Invalid course information");
        }
        if (controller.signal.aborted) return;

        if (result.data.length === 0) {
          setState({ status: "empty", data: [] });
        } else {
          setState({ status: "success", data: result.data });
        }
      } catch (error) {
        if (
          error instanceof Error &&
          error.name !== "AbortError" &&
          !controller.signal.aborted
        ) {
          setState({ status: "error", message: error.message });
        }
      }
    }

    loadCourses();
    return () => controller.abort();
  }, []);

  switch (state.status) {
    case "loading":
      return <p>Loading courses...</p>;
    case "empty":
      return <p>No courses are available.</p>;
    case "error":
      return <p>{state.message}</p>;
    case "success":
      return <CourseList courses={state.data} />;
  }
}

