function useDebouncedValue<T>(value: T, delay: number) {
  const [result, setResult] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => {
      setResult(value);
    }, delay);
    return () => clearTimeout(timer);
  }, [value, delay]);

  return result;
}

import { useMutation, useQueryClient } from "@tanstack/react-query";

function useCompleteLesson() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: completeLesson,
    onMutate: async ({ courseId, completed }) => {
      await queryClient.cancelQueries({
        queryKey: ["course", courseId]
      });

      const previousCourse = queryClient.getQueryData<Course>([
        "course",
        courseId
      ]);

      queryClient.setQueryData<Course>(
        ["course", courseId],
        old => (old ? { ...old, completed } : old)
      );

      return { previousCourse };
    },
    onError: (_error, variables, context) => {
      if (context?.previousCourse) {
        queryClient.setQueryData(
          ["course", variables.courseId],
          context.previousCourse
        );
      }
    },
    onSettled: async (_data, _error, variables) => {
      await queryClient.invalidateQueries({
        queryKey: ["course", variables.courseId]
      });
    }
  });
}

