import { useEffect, useState } from "react";

type ConnectionStatus =
  | "connecting"
  | "connected"
  | "disconnected"
  | "error";

function useWebSocket(url: string) {
  const [status, setStatus] = useState<ConnectionStatus>("connecting");
  const [messages, setMessages] = useState<string[]>([]);

  useEffect(() => {
    const socket = new WebSocket(url);
    setStatus("connecting");

    socket.addEventListener("open", () => {
      setStatus("connected");
    });

    socket.addEventListener("message", event => {
      setMessages(previous => [...previous, String(event.data)]);
    });

    socket.addEventListener("error", () => {
      setStatus("error");
    });

    socket.addEventListener("close", () => {
      setStatus("disconnected");
    });

    return () => {
      socket.close();
    };
  }, [url]);

  return { status, messages };
}

import * as z from "zod";

export const CourseSchema = z.object({
  id: z.number(),
  title: z.string(),
  description: z.string(),
  category: z.string(),
  level: z.enum(["beginner", "intermediate", "advanced"]),
  published: z.boolean(),
  thumbnail: z.string().nullable()
});

export type Course = z.infer<typeof CourseSchema>;

export const CourseListSchema = z.object({
  items: z.array(CourseSchema),
  page: z.number(),
  limit: z.number(),
  total: z.number(),
  totalPages: z.number()
});

export type CourseList = z.infer<typeof CourseListSchema>;

import * as z from "zod";
import { CourseListSchema, CourseSchema } from "../schemas/courseSchema";
import type { Course, CourseList } from "../schemas/courseSchema";

export interface CourseFilters {
  page: number;
  limit: number;
  search: string;
  level: string;
}

const API_URL = "/api/courses";

async function parseResponse<T>(
  response: Response,
  schema: z.ZodType<T>
): Promise<T> {
  if (!response.ok) {
    throw new Error(`Request failed: ${response.status}`);
  }
  const rawData: unknown = await response.json();
  return schema.parse(rawData);
}

export async function getCourses(
  filters: CourseFilters,
  signal?: AbortSignal
): Promise<CourseList> {
  const params = new URLSearchParams({
    page: String(filters.page),
    limit: String(filters.limit),
    search: filters.search,
    level: filters.level
  });

  const response = await fetch(`${API_URL}?${params.toString()}`, {
    credentials: "include",
    signal
  });

  return parseResponse(response, CourseListSchema);
}

export async function getCourse(id: number): Promise<Course> {
  const response = await fetch(`${API_URL}/${id}`, {
    credentials: "include"
  });
  return parseResponse(response, CourseSchema);
}

