    queries: {
      staleTime: 60 * 1000,
      gcTime: 5 * 60 * 1000,
      retry: 1,
      refetchOnWindowFocus: true
    },
    mutations: {
      retry: false
    }
  }
});

import { useQuery } from "@tanstack/react-query";
import { getCourses, type CourseFilters } from "../services/courseApi";

export function useCourses(filters: CourseFilters) {
  return useQuery({
    queryKey: ["courses", filters],
    queryFn: ({ signal }) => getCourses(filters, signal),
    placeholderData: previousData => previousData
  });
}

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";

const CourseFormSchema = z.object({
  title: z.string().min(3),
  description: z.string().min(10),
  level: z.enum(["beginner", "intermediate", "advanced"])
});

type CourseFormValues = z.infer<typeof CourseFormSchema>;

interface CourseFormProps {
  onSubmit: (data: CourseFormValues) => Promise<void>;
}

export function CourseForm({ onSubmit }: CourseFormProps) {
  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting }
  } = useForm<CourseFormValues>({
    resolver: zodResolver(CourseFormSchema),
    defaultValues: {
      title: "",
      description: "",
      level: "beginner"
    }
  });

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <label>Course Title</label>
      <input
        {...register("title")}
        placeholder="Enter course title"
      />
      {errors.title && <p>{errors.title.message}</p>}

      <label>Description</label>
      <textarea
        {...register("description")}
        placeholder="Enter course description"
      />
      {errors.description && <p>{errors.description.message}</p>}

      <label>Difficulty</label>
      <select {...register("level")}>
        <option value="beginner">Beginner</option>
        <option value="intermediate">Intermediate</option>
        <option value="advanced">Advanced</option>
      </select>

      <button type="submit" disabled={isSubmitting}>
        {isSubmitting ? "Saving..." : "Save Course"}
      </button>
    </form>
  );
}

import { useState } from "react";
import { useCourses } from "../hooks/useCourses";

function CoursesPage() {
  const [search, setSearch] = useState("");
  const [level, setLevel] = useState("");
  const [page, setPage] = useState(1);
  const [searchInput, setSearchInput] = useState("");

  const coursesQuery = useCourses({
    page,
    limit: 10,
    search,
    level
  });

  function handleSearch() {
    setPage(1);
    setSearch(searchInput);
  }

  function handleLevelChange(value: string) {
    setPage(1);
    setLevel(value);
  }

  if (coursesQuery.isPending) {
    return <p>Loading courses...</p>;
  }
  if (coursesQuery.isError) {
    return (
      <div>
        <p>{coursesQuery.error.message}</p>
        <button onClick={() => coursesQuery.refetch()}>
          Retry
        </button>
      </div>
    );
  }

  const courses = coursesQuery.data.items;

  return (
    <main>
      <h1>Course Management</h1>
      <input
        value={searchInput}
        onChange={event => setSearchInput(event.target.value)}
        placeholder="Search courses..."
      />
      <button onClick={handleSearch}>Search</button>

      <select
        value={level}
        onChange={event => handleLevelChange(event.target.value)}
      >
        <option value="">All Levels</option>
        <option value="beginner">Beginner</option>
        <option value="intermediate">Intermediate</option>
        <option value="advanced">Advanced</option>
      </select>

      {courses.length === 0 ? (
        <p>No courses found.</p>
      ) : (
        courses.map(course => (
          <article key={course.id}>
            <h2>{course.title}</h2>
            <p>{course.description}</p>
            <span>{course.level}</span>
          </article>
        ))
      )}

      <div>
        <button
          disabled={page <= 1}
          onClick={() => setPage(current => current - 1)}
        >
          Previous
        </button>
        <span>Page {page}</span>
        <button
          disabled={
            page >= coursesQuery.data.totalPages ||
            coursesQuery.isPlaceholderData
          }
          onClick={() => setPage(current => current + 1)}
        >
          Next
        </button>
      </div>
    </main>
  );
}

export default CoursesPage;
